/** Cor 'rgb(r, g, b)' do estilo calculado -> [r, g, b]. */
const rgb = (sel: string, prop: string) => `${cs(sel, prop)}.match(/\\d+/g).map(Number)`;
/** Há alguma regra de CSS cujo texto casa com a expressão regular (para checar @media, :hover, clamp...). */
const rule = (re: string) => `[...document.styleSheets].some((s) => [...s.cssRules].some((r) => ${re}.test(r.cssText)))`;

